//! `parity` binary: Python-vs-Rust parity sweep.
//!
//! Reads `parity_cases.json` (generated by `parity_gen.py` from the
//! Python implementation), recomputes each case in Rust, and compares:
//! BM25 top-k ids (exact) and scores (relative tolerance 1e-6), best
//! snippet-window indices (exact), and the ContextManager turn-2
//! decision (action + text, exact). Prints the mismatch count and exits
//! non-zero if it is not 0.
//!
//! Usage: `cargo run --release --bin parity -- parity_cases.json`

use std::fs;
use std::process::ExitCode;

use core_rust::jsonparse::parse;
use core_rust::mechanism::{Bm25, ContextManager, SnippetExtractor};

const REL_TOL: f64 = 1e-6;

fn rel_close(a: f64, b: f64) -> bool {
    if a == b {
        return true;
    }
    let denom = b.abs().max(1e-12);
    (a - b).abs() <= REL_TOL * denom
}

fn main() -> ExitCode {
    let path = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "parity_cases.json".to_string());
    let text = match fs::read_to_string(&path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("cannot read {}: {}", path, e);
            return ExitCode::from(2);
        }
    };
    let root = match parse(&text) {
        Ok(j) => j,
        Err(e) => {
            eprintln!("JSON parse error: {}", e);
            return ExitCode::from(2);
        }
    };
    let cases = match root.get("cases").and_then(|c| c.as_arr()) {
        Some(c) => c,
        None => {
            eprintln!("no 'cases' array in {}", path);
            return ExitCode::from(2);
        }
    };

    let mut mismatches = 0usize;
    let mut tie_order_notes = 0usize;
    for (ci, case) in cases.iter().enumerate() {
        let query = case.get("query").and_then(|v| v.as_str()).unwrap_or("");
        let passages: Vec<String> = case
            .get("passages")
            .and_then(|v| v.as_arr())
            .map(|a| {
                a.iter()
                    .map(|v| v.as_str().unwrap_or("").to_string())
                    .collect()
            })
            .unwrap_or_default();
        let sentences: Vec<String> = case
            .get("sentences")
            .and_then(|v| v.as_arr())
            .map(|a| {
                a.iter()
                    .map(|v| v.as_str().unwrap_or("").to_string())
                    .collect()
            })
            .unwrap_or_default();
        let k = case.get("k").and_then(|v| v.as_f64()).unwrap_or(5.0) as usize;
        let expected = match case.get("expected") {
            Some(e) => e,
            None => {
                eprintln!("case {}: no 'expected'", ci);
                mismatches += 1;
                continue;
            }
        };

        // ---- BM25 top-k
        let bm25 = Bm25::new(passages.clone(), 1.5, 0.75);
        let got = bm25.search(query, k);
        let exp_topk: Vec<(usize, f64)> = expected
            .get("bm25_topk")
            .and_then(|v| v.as_arr())
            .map(|a| {
                a.iter()
                    .map(|pair| {
                        let arr = pair.as_arr().unwrap_or(&[]);
                        (
                            arr.first().and_then(|v| v.as_f64()).unwrap_or(-1.0) as usize,
                            arr.get(1).and_then(|v| v.as_f64()).unwrap_or(f64::NAN),
                        )
                    })
                    .collect()
            })
            .unwrap_or_default();
        if got.len() != exp_topk.len() {
            eprintln!(
                "case {}: top-k length mismatch: rust {} vs python {}",
                ci,
                got.len(),
                exp_topk.len()
            );
            mismatches += 1;
        } else {
            let mut ids_match = true;
            let mut scores_match = true;
            for (i, ((gi, gs), (ei, es))) in got.iter().zip(exp_topk.iter()).enumerate() {
                if gi != ei {
                    ids_match = false;
                    eprintln!(
                        "case {}: top-k[{}] id mismatch: rust {} vs python {} (scores rust {:.17} python {:.17})",
                        ci, i, gi, ei, gs, es
                    );
                }
                if !rel_close(*gs, *es) {
                    scores_match = false;
                    eprintln!(
                        "case {}: top-k[{}] score mismatch: rust {:.17} vs python {:.17}",
                        ci, i, gs, es
                    );
                }
            }
            if !ids_match {
                // Diagnose a pure tie-order swap: same (id, score) multiset.
                let mut g: Vec<(usize, f64)> = got.clone();
                let mut e: Vec<(usize, f64)> = exp_topk.clone();
                g.sort_by_key(|(i, _)| *i);
                e.sort_by_key(|(i, _)| *i);
                let same_multiset = g.len() == e.len()
                    && g.iter()
                        .zip(e.iter())
                        .all(|((gi, gs), (ei, es))| gi == ei && rel_close(*gs, *es));
                if same_multiset {
                    tie_order_notes += 1;
                    eprintln!(
                        "case {}: NOTE ids differ but the (id, score) multiset matches — a tie-order swap within float noise",
                        ci
                    );
                }
                mismatches += 1;
            }
            if !scores_match {
                mismatches += 1;
            }
        }

        // ---- best snippet window on sentences[0..] (passage 0)
        let all_sentences: Vec<String> = case
            .get("all_sentences")
            .and_then(|v| v.as_arr())
            .map(|a| {
                a.iter()
                    .map(|v| v.as_str().unwrap_or("").to_string())
                    .collect()
            })
            .unwrap_or_default();
        let extractor = SnippetExtractor::new(&all_sentences);
        let (got_idx, _got_text) = extractor.best_window(&sentences, query, 2);
        let exp_idx: Vec<usize> = expected
            .get("best_window")
            .and_then(|v| v.as_arr())
            .map(|a| {
                a.iter()
                    .map(|v| v.as_f64().unwrap_or(-1.0) as usize)
                    .collect()
            })
            .unwrap_or_default();
        if got_idx != exp_idx {
            eprintln!(
                "case {}: best_window mismatch: rust {:?} vs python {:?}",
                ci, got_idx, exp_idx
            );
            mismatches += 1;
        }

        // ---- ContextManager turn-2 decision
        let supp = expected.get("suppression");
        let (registered, fresh, answer) = match supp {
            Some(s) => (
                s.get("registered").and_then(|v| v.as_str()).unwrap_or(""),
                s.get("fresh").and_then(|v| v.as_str()).unwrap_or(""),
                s.get("answer_sentence")
                    .and_then(|v| v.as_str())
                    .unwrap_or(""),
            ),
            None => ("", "", ""),
        };
        let mut cm = ContextManager::new(0.8);
        cm.register("p0", registered);
        let (action, text) = cm.turn2_decision("p0", fresh, answer);
        let exp_action = supp
            .and_then(|s| s.get("action"))
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let exp_text = supp
            .and_then(|s| s.get("text"))
            .and_then(|v| v.as_str())
            .unwrap_or("");
        if action.as_str() != exp_action || text != exp_text {
            eprintln!(
                "case {}: suppression mismatch: rust ({}, {:?}) vs python ({}, {:?})",
                ci,
                action.as_str(),
                text,
                exp_action,
                exp_text
            );
            mismatches += 1;
        }
    }

    println!(
        "parity sweep: {} cases, {} mismatches ({} tie-order notes)",
        cases.len(),
        mismatches,
        tie_order_notes
    );
    if mismatches == 0 {
        ExitCode::SUCCESS
    } else {
        ExitCode::from(1)
    }
}
